use vstd::prelude::*;

verus! {

pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {
    pub open spec fn head(self) -> T {
        (self.nat_to_state)(0)
    }
    pub open spec fn head_next(self) -> T {
        (self.nat_to_state)(1)
    }
    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }
}

pub type StatePred<T> = spec_fn(T) -> bool;
pub type ActionPred<T> = spec_fn(T, T) -> bool;

proof fn init_invariant_induction_helper<T>(
    ex: Execution<T>, 
    i: nat, 
    init: StatePred<T>, 
    next: ActionPred<T>, 
    inv: StatePred<T>
)
    requires
        forall |s: T| #[trigger] init(s) ==> inv(s),
        forall |s, s_prime: T| inv(s) && #[trigger] next(s, s_prime) ==> inv(s_prime),
        init(ex.head()),
        forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next()),
    ensures inv(ex.suffix(i).head())
    decreases i
{
    if i == 0 {
        // ex.suffix(0).head() == ex.head()
        assert(ex.suffix(0 as nat).head() == ex.head()) by {
            // Both reduce to ex.nat_to_state(0)
        };
    } else {
        let i_minus_1 = (i - 1) as nat;
        init_invariant_induction_helper(ex, i_minus_1, init, next, inv);
        // We have inv(ex.suffix(i-1).head())
        // We need next(ex.suffix(i-1).head(), ex.suffix(i).head())
        assert(ex.suffix(i_minus_1).head_next() == ex.suffix(i).head()) by {
            // ex.suffix(i-1).head_next() = (ex.nat_to_state)(1 + (i-1)) = (ex.nat_to_state)(i)
            // ex.suffix(i).head() = (ex.nat_to_state)(0 + i) = (ex.nat_to_state)(i)
        };
        assert(next(ex.suffix(i_minus_1).head(), ex.suffix(i_minus_1).head_next()));
    }
}

fn main() {}

}
