use vstd::prelude::*;

verus! {

pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {
    pub open spec fn head(self) -> T { (self.nat_to_state)(0) }
    pub open spec fn head_next(self) -> T { (self.nat_to_state)(1) }
    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution { nat_to_state: |i: nat| (self.nat_to_state)(i + pos) }
    }
}

pub type StatePred<T> = spec_fn(T) -> bool;
pub type ActionPred<T> = spec_fn(T, T) -> bool;

pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {
    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self { TempPred { pred } }
    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool { (self.pred)(execution) }
    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }
    pub open spec fn entails(self, other: Self) -> bool { valid(self.implies(other)) }
}

pub open spec fn lift_state<T>(state_pred: StatePred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| state_pred(ex.head()))
}
pub open spec fn lift_action<T>(action_pred: ActionPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| action_pred(ex.head(), ex.head_next()))
}
pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}
pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}

proof fn init_invariant_helper<T>(
    ex: Execution<T>, i: nat, init: StatePred<T>, next: ActionPred<T>, inv: StatePred<T>
)
    requires
        forall |s: T| #[trigger] init(s) ==> inv(s),
        forall |s, s_prime: T| inv(s) && #[trigger] next(s, s_prime) ==> inv(s_prime),
        init(ex.head()),
        forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next()),
    ensures inv(ex.suffix(i).head())
    decreases i
{
    if i == 0 {
        assert(ex.suffix(0 as nat).head() == ex.head());
    } else {
        let j = (i - 1) as nat;
        init_invariant_helper(ex, j, init, next, inv);
        assert(ex.suffix(j).head_next() == ex.suffix(i).head());
        assert(next(ex.suffix(j).head(), ex.suffix(j).head_next()));
    }
}

pub proof fn init_invariant<T>(spec: TempPred<T>, init: StatePred<T>, next: ActionPred<T>, inv: StatePred<T>)
    requires
        forall |s: T| #[trigger] init(s) ==> inv(s),
        forall |s, s_prime: T| inv(s) && #[trigger] next(s, s_prime) ==> inv(s_prime),
        spec.entails(lift_state(init)),
        spec.entails(always(lift_action(next))),
    ensures spec.entails(always(lift_state(inv)))
{
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies always(lift_state(inv)).satisfied_by(ex) by {
        assert forall |i: nat| #[trigger] lift_state(inv).satisfied_by(ex.suffix(i)) by {
            assert(init(ex.head())) by {
                assert(spec.entails(lift_state(init)));
            };
            assert(forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next())) by {
                assert(always(lift_action(next)).satisfied_by(ex));
            };
            init_invariant_helper(ex, i, init, next, inv);
        };
    };
}

fn main() {}

}
