pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {
    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self { TempPred { pred } }
    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool { (self.pred)(execution) }
    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }
    pub open spec fn entails(self, other: Self) -> bool { valid(self.implies(other)) }
}

pub open spec fn lift_state<T>(state_pred: StatePred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| state_pred(ex.head()))
}
pub open spec fn lift_action<T>(action_pred: ActionPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| action_pred(ex.head(), ex.head_next()))
}
pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}
pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}

// Supporting invariant - proved as external body
#[verifier::external_body]
pub proof fn lemma_always_supporting(spec: TempPred<State>)
    requires
        spec.entails(lift_state(|s: State| s.v == 0 || s.v > 0)),
        spec.entails(always(lift_action(|s: State, s_prime: State| s_prime.v == s.v + 1))),
    ensures spec.entails(always(lift_state(|s: State| s.v >= 0)))
{
    unimplemented!()
}

// Main invariant that depends on supporting
pub open spec fn main_inv(s: State) -> bool {
    s.w >= 0 && s.w <= s.v + 100
}

// Helper for main inv
proof fn main_inv_helper(
    spec: TempPred<State>,
    ex: Execution<State>,
    i: nat
)
    requires
        spec.satisfied_by(ex),
        spec.entails(lift_state(|s: State| s.v == 0 || s.v > 0)),
        spec.entails(always(lift_action(|s: State, s_prime: State| s_prime.v == s.v + 1))),
        // From init: v=0, w=0
        ex.head() == State { v: 0, w: 0 },
    ensures main_inv(ex.suffix(i).head())
    decreases i
{
    // Get supporting invariant
    lemma_always_supporting(spec);
    // This gives us: forall j, s.v >= 0 at step j

    if i == 0 {
        assert(ex.suffix(0 as nat).head() == ex.head());
        assert(main_inv(ex.head()));
    } else {
        main_inv_helper(spec, ex, (i-1) as nat);
        let s = ex.suffix((i-1) as nat).head();
        let s_prime = ex.suffix(i).head();
        // next(s, s_prime)
        assert(always(lift_action(|s: State, s_prime: State| s_prime.v == s.v + 1)).satisfied_by(ex));
        // ...
    }
}

