// Helper lemma for init_invariant: inductive step on nat
proof fn init_invariant_induction_helper<T>(
    ex: Execution<T>,
    i: nat,
    init: StatePred<T>,
    next: ActionPred<T>,
    inv: StatePred<T>,
)
    requires
        forall |s: T| #[trigger] init(s) ==> inv(s),
        forall |s, s_prime: T| inv(s) && #[trigger] next(s, s_prime) ==> inv(s_prime),
        init(ex.head()),
        forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next()),
    ensures inv(ex.suffix(i).head())
    decreases i
{
    if i == 0 {
        // ex.suffix(0).head() = (ex.nat_to_state)(0) = ex.head()
        assert(ex.suffix(0 as nat).head() == ex.head());
    } else {
        let j = (i - 1) as nat;
        init_invariant_induction_helper(ex, j, init, next, inv);
        // inv(ex.suffix(j).head()) is established
        // next(ex.suffix(j).head(), ex.suffix(j).head_next())
        assert(next(ex.suffix(j).head(), ex.suffix(j).head_next()));
        // ex.suffix(j).head_next() == ex.suffix(i).head() since both = ex.nat_to_state(i)
        assert(ex.suffix(j).head_next() == ex.suffix(i).head());
    }
}

pub proof fn init_invariant<T>(spec: TempPred<T>, init: StatePred<T>, next: ActionPred<T>, inv: StatePred<T>)
    requires
        forall |s: T| #[trigger] init(s) ==> inv(s),
        forall |s, s_prime: T| inv(s) && #[trigger] next(s, s_prime) ==> inv(s_prime),
        spec.entails(lift_state(init)),
        spec.entails(always(lift_action(next))),
    ensures spec.entails(always(lift_state(inv))),
    {
        let init_pred = lift_state(init);
        let always_next = always(lift_action(next));
        let always_inv = always(lift_state(inv));
        assert forall |ex: Execution<T>| #[trigger] (spec.implies(always_inv)).satisfied_by(ex) by {
            if spec.satisfied_by(ex) {
                // Extract: init holds at head
                assert((spec.implies(init_pred)).satisfied_by(ex)) by {
                    assert(valid(spec.implies(init_pred)));
                };
                assert(init_pred.satisfied_by(ex));
                assert(init(ex.head()));
                // Extract: always(next) holds
                assert((spec.implies(always_next)).satisfied_by(ex)) by {
                    assert(valid(spec.implies(always_next)));
                };
                assert(always_next.satisfied_by(ex));
                // Unfold always(next): forall j, next(ex.suffix(j).head(), ex.suffix(j).head_next())
                assert(forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next())) by {
                    assert forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next()) by {
                        assert(lift_action(next).satisfied_by(ex.suffix(j)));
                    };
                };
                // Prove inv at every position by induction
                assert forall |i: nat| #[trigger] lift_state(inv).satisfied_by(ex.suffix(i)) by {
                    init_invariant_induction_helper(ex, i, init, next, inv);
                };
                assert(always_inv.satisfied_by(ex));
            }
        };
    }

