use verus_builtin::*;
use verus_builtin_macros::*;

fn main() {}

verus! {

// Minimal types needed
pub type StringView = Seq<char>;
pub type ResourceVersion = int;
pub type Uid = int;
pub type Value = StringView;

#[is_variant]
pub enum Kind {
    PodKind,
    CustomResourceKind(StringView),
}

pub struct ObjectRef {
    pub kind: Kind,
    pub name: StringView,
    pub namespace: StringView,
}

pub struct ObjectMetaView {
    pub name: Option<StringView>,
    pub namespace: Option<StringView>,
    pub resource_version: Option<ResourceVersion>,
    pub uid: Option<Uid>,
    pub owner_references: Option<Seq<()>>,
    pub deletion_timestamp: Option<StringView>,
    pub finalizers: Option<Seq<StringView>>,
    pub generate_name: Option<StringView>,
    pub labels: Option<Map<StringView, StringView>>,
    pub annotations: Option<Map<StringView, StringView>>,
}

impl ObjectMetaView {
    pub open spec fn well_formed_for_namespaced(self) -> bool {
        self.name is Some && self.namespace is Some && self.resource_version is Some && self.uid is Some
    }
}

pub struct DynamicObjectView {
    pub kind: Kind,
    pub metadata: ObjectMetaView,
    pub spec: Value,
    pub status: Value,
}

impl DynamicObjectView {
    pub open spec fn object_ref(self) -> ObjectRef {
        ObjectRef {
            kind: self.kind,
            name: self.metadata.name->0,
            namespace: self.metadata.namespace->0,
        }
    }
    pub open spec fn with_resource_version(self, rv: ResourceVersion) -> DynamicObjectView {
        DynamicObjectView {
            metadata: ObjectMetaView { resource_version: Some(rv), ..self.metadata },
            ..self
        }
    }
}

pub type StoredState = Map<ObjectRef, DynamicObjectView>;

pub struct APIServerState {
    pub resources: StoredState,
    pub uid_counter: Uid,
    pub resource_version_counter: ResourceVersion,
}

// Lemma: same RV in s and s_prime implies same object (for handle_create_request case)
// This is a key property needed for the main proof
proof fn lemma_same_rv_implies_same_obj_create(
    resources: StoredState, rv_counter: ResourceVersion,
    new_resources: StoredState, new_rv_counter: ResourceVersion,
    new_key: ObjectRef, new_obj: DynamicObjectView,
)
    requires
        new_obj.metadata.resource_version == Some(rv_counter),
        new_rv_counter == rv_counter + 1,
        new_resources == resources.insert(new_key, new_obj),
        // existing objects have rv < rv_counter
        forall |key: ObjectRef| 
            #[trigger] resources.contains_key(key) 
            ==> resources[key].metadata.resource_version is Some
                && resources[key].metadata.resource_version->0 < rv_counter,
    ensures
        // For any key in new_resources with rv < rv_counter, same as in resources
        forall |key: ObjectRef|
            #[trigger] new_resources.contains_key(key)
            && new_resources[key].metadata.resource_version is Some
            && new_resources[key].metadata.resource_version->0 < rv_counter
            ==> resources.contains_key(key) && resources[key] == new_resources[key]
{
    assert forall |key: ObjectRef|
        #[trigger] new_resources.contains_key(key)
        && new_resources[key].metadata.resource_version is Some
        && new_resources[key].metadata.resource_version->0 < rv_counter
        implies resources.contains_key(key) && resources[key] == new_resources[key]
    by {
        if key == new_key {
            // new_obj has rv = rv_counter, but we assumed rv < rv_counter
            // contradiction
            assert(new_resources[key] == new_obj);
            assert(new_obj.metadata.resource_version->0 == rv_counter);
            assert(false);
        } else {
            // key is in resources (unchanged)
            assert(new_resources[key] == resources[key]);
        }
    };
}

}
