// Helper: for API server steps that insert or update a key with RV = s.rv_counter,
// any existing key in s_prime with rv < s.rv_counter was unchanged from s
proof fn lemma_api_server_rv_monotone(
    s: ClusterState, s_prime: ClusterState,
)
    requires
        // After an API server step, rv_counter only increases
        s_prime.api_server.resource_version_counter >= s.api_server.resource_version_counter,
        // Any new or updated key in s_prime gets RV >= s.rv_counter
        forall |key: ObjectRef|
            #[trigger] s_prime.resources().contains_key(key) 
            && !(s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key])
            ==> s_prime.resources()[key].metadata.resource_version is Some
                && s_prime.resources()[key].metadata.resource_version->0 >= s.api_server.resource_version_counter,
        // Existing objects have rv < old rv_counter
        forall |key: ObjectRef|
            #[trigger] s.resources().contains_key(key)
            ==> s.resources()[key].metadata.resource_version is Some
                && s.resources()[key].metadata.resource_version->0 < s.api_server.resource_version_counter,
    ensures
        // If an object in s_prime has rv < s.rv_counter, it's unchanged from s
        forall |key: ObjectRef|
            #[trigger] s_prime.resources().contains_key(key)
            && s_prime.resources()[key].metadata.resource_version is Some
            && s_prime.resources()[key].metadata.resource_version->0 < s.api_server.resource_version_counter
            ==> s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key]
{
    assert forall |key: ObjectRef|
        #[trigger] s_prime.resources().contains_key(key)
        && s_prime.resources()[key].metadata.resource_version is Some
        && s_prime.resources()[key].metadata.resource_version->0 < s.api_server.resource_version_counter
        implies s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key]
    by {
        if s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key] {
            // already the case
        } else {
            // By the second hypothesis: rv >= s.rv_counter, but we assumed rv < s.rv_counter -> contradiction
            assert(s_prime.resources()[key].metadata.resource_version->0 >= s.api_server.resource_version_counter);
            assert(false);
        }
    };
}

// Helper: prove the "contains_key && same_rv => owner_ref" condition is preserved
// when the resource might have changed
proof fn lemma_owner_ref_cond_preserved(
    s: ClusterState, s_prime: ClusterState,
    pod: PodView, triggering_cr: VReplicaSetView,
)
    requires
        pod.metadata.resource_version is Some,
        pod.metadata.resource_version->0 < s.api_server.resource_version_counter,
        s_prime.api_server.resource_version_counter >= s.api_server.resource_version_counter,
        // If s had pod at same rv, it owned vrs
        (s.resources().contains_key(pod.object_ref())
            && s.resources()[pod.object_ref()].metadata.resource_version == pod.metadata.resource_version)
        ==> s.resources()[pod.object_ref()].metadata.owner_references_contains(triggering_cr.controller_owner_ref()),
        // Same RV in s_prime means unchanged from s
        forall |key: ObjectRef|
            #[trigger] s_prime.resources().contains_key(key)
            && s_prime.resources()[key].metadata.resource_version is Some
            && s_prime.resources()[key].metadata.resource_version->0 < s.api_server.resource_version_counter
            ==> s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key],
    ensures
        (s_prime.resources().contains_key(pod.object_ref())
            && s_prime.resources()[pod.object_ref()].metadata.resource_version == pod.metadata.resource_version)
        ==> s_prime.resources()[pod.object_ref()].metadata.owner_references_contains(triggering_cr.controller_owner_ref()),
{
    let key = pod.object_ref();
    if s_prime.resources().contains_key(key)
        && s_prime.resources()[key].metadata.resource_version == pod.metadata.resource_version {
        // pod.rv < s.rv_counter, so by lemma, s.resources[key] == s_prime.resources[key]
        assert(s_prime.resources()[key].metadata.resource_version->0 < s.api_server.resource_version_counter);
        assert(s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key]);
        // From s's property: s.resources[key].owner_ref_contains vrs
        assert(s.resources()[key].metadata.resource_version == pod.metadata.resource_version);
        assert(s.resources()[key].metadata.owner_references_contains(triggering_cr.controller_owner_ref()));
        assert(s_prime.resources()[key].metadata.owner_references_contains(triggering_cr.controller_owner_ref()));
    }
}

