// Key API server property: after an API server step,
// modified objects have rv >= old rv_counter,
// and rv_counter only increases
#[verifier(rlimit(50))]
proof fn lemma_api_server_step_properties(
    cluster: Cluster, s: ClusterState, s_prime: ClusterState, msg: Message,
)
    requires
        s_prime == (cluster.api_server_next().transition)(Some(msg), s).0,
        (cluster.api_server_next().precondition)(Some(msg), s),
    ensures
        s_prime.api_server.resource_version_counter >= s.api_server.resource_version_counter,
        s_prime.controller_and_externals == s.controller_and_externals,
        s_prime.rpc_id_allocator == s.rpc_id_allocator,
        // Modified objects (different from s) have rv >= s.rv_counter
        forall |key: ObjectRef|
            #[trigger] s_prime.resources().contains_key(key)
            && !(s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key])
            ==> s_prime.resources()[key].metadata.resource_version is Some
                && s_prime.resources()[key].metadata.resource_version->0 >= s.api_server.resource_version_counter,
{
    // Unfold api_server_next
    let api_input = APIServerActionInput { recv: Some(msg) };
    let req = msg.content.get_APIRequest_0();
    let api_s = s.api_server;
    // The API server state machine handles the request
    // Let's trace through transition_by_etcd to see what happens

    // The API server only changes resources by inserting/removing keys
    // Any inserted key gets resource_version = s.resource_version_counter
    // resource_version_counter either stays the same or increases by 1

    // This requires unfolding the API server transitions
    // For all cases, the transitions either:
    // - Don't change resources (Get, List, failed writes)
    // - Insert a new key with rv = s.rv_counter (Create, Update that changes, GetThenUpdate)
    // - Remove a key (Delete without finalizers, GetThenDelete, Update that triggers delete)
    // - Set a key with rv = s.rv_counter (Delete with finalizers adds deletion_timestamp with new rv)

    // In all cases where resources change, the modified object gets rv = s.rv_counter
    // and rv_counter becomes s.rv_counter + 1

    // To formally prove this, we need to case split on the request type
    match req {
        APIRequest::GetRequest(_) => {
            // No state change
            assert(s_prime.api_server == api_s);
        },
        APIRequest::ListRequest(_) => {
            // No state change
            assert(s_prime.api_server == api_s);
        },
        APIRequest::CreateRequest(create_req) => {
            // handle_create_request either fails (no change) or creates with rv = s.rv_counter
            let (new_api_s, _) = handle_create_request(cluster.installed_types, create_req, api_s);
            assert(s_prime.api_server == new_api_s);
            // If create succeeds, the new object has rv = s.rv_counter
            // If create fails, no change
        },
        APIRequest::DeleteRequest(delete_req) => {
            let (new_api_s, _) = handle_delete_request(delete_req, api_s);
            assert(s_prime.api_server == new_api_s);
        },
        APIRequest::UpdateRequest(update_req) => {
            let (new_api_s, _) = handle_update_request(cluster.installed_types, update_req, api_s);
            assert(s_prime.api_server == new_api_s);
        },
        APIRequest::UpdateStatusRequest(update_status_req) => {
            let (new_api_s, _) = handle_update_status_request(cluster.installed_types, update_status_req, api_s);
            assert(s_prime.api_server == new_api_s);
        },
        APIRequest::GetThenDeleteRequest(gtd_req) => {
            let (new_api_s, _) = handle_get_then_delete_request_msg(msg, api_s);
            assert(s_prime.api_server == new_api_s);
        },
        APIRequest::GetThenUpdateRequest(gtu_req) => {
            let (new_api_s, _) = handle_get_then_update_request_msg(cluster.installed_types, msg, api_s);
            assert(s_prime.api_server == new_api_s);
        },
    }
}

// Prove the main invariant's inductive step for steps that don't modify ongoing_reconciles(controller_id)
// but might change resources and in_flight
#[verifier(rlimit(50))]
proof fn lemma_main_inv_preserved_by_non_controller_step(
    cluster: Cluster, controller_id: int,
    s: ClusterState, s_prime: ClusterState,
)
    requires
        cluster.next()(s, s_prime),
        cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
        // ongoing_reconciles(controller_id) is unchanged
        s.ongoing_reconciles(controller_id) == s_prime.ongoing_reconciles(controller_id),
        // in_flight is a superset (or might have had one msg removed and new added)
        // resource_version_counter only increases
        s_prime.api_server.resource_version_counter >= s.api_server.resource_version_counter,
        // Modified objects in s_prime have rv >= s.rv_counter
        forall |key: ObjectRef|
            #[trigger] s_prime.resources().contains_key(key)
            && !(s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key])
            ==> s_prime.resources()[key].metadata.resource_version is Some
                && s_prime.resources()[key].metadata.resource_version->0 >= s.api_server.resource_version_counter,
        // Existing objects have rv < s.rv_counter
        forall |key: ObjectRef|
            #[trigger] s.resources().contains_key(key)
            ==> s.resources()[key].metadata.resource_version is Some
                && s.resources()[key].metadata.resource_version->0 < s.api_server.resource_version_counter,
        // Main invariant in s
        each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)(s),
        // in_flight in s is a subset of in_flight in s_prime union the one removed
        // For the AfterListPods invariant, new in-flight responses must be valid
        // Simplification: we handle the new in-flight response separately
        // Assume that for any new message added to in_flight that matches a pending list request,
        // the message's list response has valid properties
        // This is the key property that comes from the API server generating the response
        forall |vrs_key: ObjectRef, resp_msg: Message|
            s.ongoing_reconciles(controller_id).contains_key(vrs_key)
            && {
                let state = VReplicaSetReconcileState::unmarshal(s.ongoing_reconciles(controller_id)[vrs_key].local_state).unwrap();
                state.reconcile_step.is_AfterListPods()
            }
            && {
                let pending_req = s.ongoing_reconciles(controller_id)[vrs_key].pending_req_msg->0;
                #[trigger] s_prime.in_flight().contains(resp_msg)
                && !s.in_flight().contains(resp_msg)
                && resp_msg.src.is_APIServer()
                && resp_msg_matches_req_msg(resp_msg, pending_req)
                && is_ok_resp(resp_msg.content.get_APIResponse_0())
            }
            ==> {
                let triggering_cr = VReplicaSetView::unmarshal(s.ongoing_reconciles(controller_id)[vrs_key].triggering_cr).unwrap();
                let resp_objs = resp_msg.content.get_list_response().res.unwrap();
                &&& resp_msg.content.is_list_response()
                &&& resp_msg.content.get_list_response().res is Ok
                &&& resp_objs.filter(|o: DynamicObjectView| PodView::unmarshal(o).is_err()).len() == 0
                &&& forall |i| #![trigger resp_objs[i]] 0 <= i < resp_objs.len() ==>
                (
                    resp_objs[i].metadata.namespace.is_some()
                    && resp_objs[i].metadata.namespace.unwrap() == triggering_cr.metadata.namespace.unwrap()
                    && ((s_prime.resources().contains_key(resp_objs[i].object_ref())
                            && s_prime.resources()[resp_objs[i].object_ref()].metadata.resource_version
                            == resp_objs[i].metadata.resource_version) ==>
                            s_prime.resources()[resp_objs[i].object_ref()].metadata
                                == resp_objs[i].metadata)
                    && resp_objs[i].metadata.resource_version.is_some()
                    && resp_objs[i].metadata.resource_version.unwrap()
                            < s_prime.api_server.resource_version_counter
                )
            },
    ensures each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)(s_prime),
{
    // Get the "same rv means same obj" property
    lemma_api_server_rv_monotone(s, s_prime);

    assert forall |key: ObjectRef|
        #[trigger] s_prime.ongoing_reconciles(controller_id).contains_key(key)
        implies {
            let state = VReplicaSetReconcileState::unmarshal(s_prime.ongoing_reconciles(controller_id)[key].local_state).unwrap();
            let triggering_cr = VReplicaSetView::unmarshal(s_prime.ongoing_reconciles(controller_id)[key].triggering_cr).unwrap();
            let filtered_pods = state.filtered_pods.unwrap();
            &&& triggering_cr.object_ref() == key
            &&& triggering_cr.metadata().well_formed_for_namespaced()
            &&& state.filtered_pods is Some ==>
                forall |i| #![trigger filtered_pods[i]] 0 <= i < filtered_pods.len() ==>
                (
                    filtered_pods[i].object_ref().namespace == triggering_cr.metadata.namespace.unwrap()
                    && ((s_prime.resources().contains_key(filtered_pods[i].object_ref())
                            && s_prime.resources()[filtered_pods[i].object_ref()].metadata.resource_version
                                == filtered_pods[i].metadata.resource_version) ==>
                        (s_prime.resources()[filtered_pods[i].object_ref()].metadata.owner_references_contains(
                            triggering_cr.controller_owner_ref()
                            )
                         ))
                    && filtered_pods[i].metadata.resource_version.is_some()
                    && filtered_pods[i].metadata.resource_version.unwrap()
                        < s_prime.api_server.resource_version_counter
                )
            &&& state.reconcile_step.is_AfterListPods() ==> {
                let req_msg = s_prime.ongoing_reconciles(controller_id)[key].pending_req_msg->0;
                &&& s_prime.ongoing_reconciles(controller_id)[triggering_cr.object_ref()].pending_req_msg is Some
                &&& req_msg.dst.is_APIServer()
                &&& req_msg.content.is_list_request()
                &&& req_msg.content.get_list_request() == ListRequest {
                    kind: PodView::kind(),
                    namespace: triggering_cr.metadata.namespace.unwrap(),
                }
                &&& forall |msg| {
                    let req_msg = s_prime.ongoing_reconciles(controller_id)[triggering_cr.object_ref()].pending_req_msg->0;
                    &&& #[trigger] s_prime.in_flight().contains(msg)
                    &&& s_prime.ongoing_reconciles(controller_id)[triggering_cr.object_ref()].pending_req_msg is Some
                    &&& msg.src.is_APIServer()
                    &&& resp_msg_matches_req_msg(msg, req_msg)
                    &&& is_ok_resp(msg.content.get_APIResponse_0())
                } ==> {
                    let resp_objs = msg.content.get_list_response().res.unwrap();
                    &&& msg.content.is_list_response()
                    &&& msg.content.get_list_response().res is Ok
                    &&& resp_objs.filter(|o: DynamicObjectView| PodView::unmarshal(o).is_err()).len() == 0
                    &&& forall |i| #![trigger resp_objs[i]] 0 <= i < resp_objs.len() ==>
                    (
                        resp_objs[i].metadata.namespace.is_some()
                        && resp_objs[i].metadata.namespace.unwrap() == triggering_cr.metadata.namespace.unwrap()
                        && ((s_prime.resources().contains_key(resp_objs[i].object_ref())
                                && s_prime.resources()[resp_objs[i].object_ref()].metadata.resource_version
                                == resp_objs[i].metadata.resource_version) ==>
                                s_prime.resources()[resp_objs[i].object_ref()].metadata
                                    == resp_objs[i].metadata)
                        && resp_objs[i].metadata.resource_version.is_some()
                        && resp_objs[i].metadata.resource_version.unwrap()
                                < s_prime.api_server.resource_version_counter
                    )
                }
            }
        }
    by {
        // Since ongoing_reconciles is unchanged
        assert(s_prime.ongoing_reconciles(controller_id)[key] == s.ongoing_reconciles(controller_id)[key]);
        let or = s.ongoing_reconciles(controller_id)[key];
        let state = VReplicaSetReconcileState::unmarshal(or.local_state).unwrap();
        let triggering_cr = VReplicaSetView::unmarshal(or.triggering_cr).unwrap();
        let filtered_pods = state.filtered_pods.unwrap();

        // Get properties from s (by induction hypothesis)
        assert(s.ongoing_reconciles(controller_id).contains_key(key));

        // Part A: triggering_cr properties
        assert(triggering_cr.object_ref() == key);
        assert(triggering_cr.metadata().well_formed_for_namespaced());

        // Part B: filtered_pods
        if state.filtered_pods is Some {
