                            == resp_objs[i].metadata.resource_version) ==>
                            s_prime.resources()[resp_objs[i].object_ref()].metadata
                                == resp_objs[i].metadata)
                    && resp_objs[i].metadata.resource_version.is_some()
                    && resp_objs[i].metadata.resource_version.unwrap()
                            < s_prime.api_server.resource_version_counter
                )
            }
            by {
                let req_msg = s_prime.ongoing_reconciles(controller_id)[triggering_cr.object_ref()].pending_req_msg->0;
                if s.in_flight().contains(resp_msg) {
                    // resp_msg was in s: use invariant from s
                    let resp_objs = resp_msg.content.get_list_response().res.unwrap();
                    assert(resp_msg.content.is_list_response());
                    assert(resp_msg.content.get_list_response().res is Ok);
                    assert(resp_objs.filter(|o: DynamicObjectView| PodView::unmarshal(o).is_err()).len() == 0);
                    // Properties of resp_objs in s
                    assert(forall |i| #![trigger resp_objs[i]] 0 <= i < resp_objs.len() ==>
                        resp_objs[i].metadata.resource_version is Some
                        && resp_objs[i].metadata.resource_version->0 < s.api_server.resource_version_counter);
                    // Preserve to s_prime
                    lemma_resp_objs_preserved(s, s_prime, resp_objs, triggering_cr);
                } else {
                    // resp_msg is new in s_prime: use the new-message property
                    // This comes from the API server generating the response
                }
            };
        };
    };
}

#[verifier(rlimit(100))]
pub proof fn lemma_always_each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(
    spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
)
    requires
        spec.entails(lift_state(cluster.init())),
        spec.entails(always(lift_action(cluster.next()))),
        cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
        cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
    ensures spec.entails(always(lift_state(each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)))),
{
    let inv = each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id);

    // Get supporting invariants
    cluster.lemma_always_each_object_in_etcd_is_weakly_well_formed(spec);
    cluster.lemma_always_each_object_in_reconcile_has_consistent_key_and_valid_metadata(spec, controller_id);
    cluster.lemma_always_cr_objects_in_reconcile_satisfy_state_validation::<VReplicaSetView>(spec, controller_id);
    cluster.lemma_always_every_in_flight_msg_has_unique_id(spec);
    cluster.lemma_always_every_in_flight_msg_has_lower_id_than_allocator(spec);
    cluster.lemma_always_every_in_flight_req_msg_has_different_id_from_pending_req_msg_of_every_ongoing_reconcile(spec, controller_id);

    assert forall |s: ClusterState| #[trigger] cluster.init()(s) implies inv(s) by {
        lemma_main_inv_holds_at_init(cluster, controller_id, s);
    };

    assert forall |s: ClusterState, s_prime: ClusterState|
        inv(s) && #[trigger] cluster.next()(s, s_prime) implies inv(s_prime)
    by {
        lemma_main_inv_inductive_step(cluster, controller_id, s, s_prime);
    };

    init_invariant(spec, cluster.init(), cluster.next(), inv);
}

// The key inductive step - proves invariant is preserved by all steps
#[verifier(rlimit(200))]
proof fn lemma_main_inv_inductive_step(
    cluster: Cluster, controller_id: int,
    s: ClusterState, s_prime: ClusterState,
)
    requires
        cluster.next()(s, s_prime),
        cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
        cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
        each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)(s),
    ensures each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)(s_prime),
{
    // There exists a step witness
    let step = choose |step: Step| cluster.next_step(s, s_prime, step);
    match step {
        Step::APIServerStep(input) => {
            // The API server step: handles a message
            // ongoing_reconciles is unchanged
            assert(s_prime.controller_and_externals == s.controller_and_externals);
            assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));

            // rv_counter only increases
            assert(s_prime.api_server.resource_version_counter >= s.api_server.resource_version_counter);

            // Prove the "same rv means same obj" property
            // Any modified object gets rv = s.rv_counter
            // Show this by casing on the request
            if input is Some {
                let msg = input->0;
                // The API server processed msg
                assert((cluster.api_server_next().precondition)(Some(msg), s));
                // Case split on request type to establish rv properties
                let req = msg.content.get_APIRequest_0();
                match req {
                    APIRequest::ListRequest(_) => {
                        // List request doesn't change resources
                        assert(s_prime.api_server.resources == s.api_server.resources);
                        assert(s_prime.api_server.resource_version_counter == s.api_server.resource_version_counter);
                        // Trivially: no modified objects
                        assert(forall |key: ObjectRef|
                            #[trigger] s_prime.resources().contains_key(key)
                            && !(s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key])
                            ==> false);
                    },
                    APIRequest::GetRequest(_) => {
                        assert(s_prime.api_server.resources == s.api_server.resources);
                        assert(s_prime.api_server.resource_version_counter == s.api_server.resource_version_counter);
                        assert(forall |key: ObjectRef|
                            #[trigger] s_prime.resources().contains_key(key)
                            && !(s.resources().contains_key(key) && s.resources()[key] == s_prime.resources()[key])
                            ==> false);
                    },
                    _ => {
                        // Other requests may change resources, but they set rv = s.rv_counter
                        // We need to show this...
                        // For now, use lemma_api_server_step_properties
                        lemma_api_server_step_properties(cluster, s, s_prime, msg);
                    },
                }
            };

            // Apply the non-controller-step lemma
            // But we need to handle the in-flight message addition
            // For the new list response case, use the API server's handle_list_request
            // to show the response has good properties
            // For simplicity, first prove without the new-msg property

            // Use the approach: prove directly
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::BuiltinControllersStep(_) => {
            // Builtin controllers only send messages, don't change ongoing_reconciles or resources directly
            assert(s_prime.controller_and_externals == s.controller_and_externals);
            assert(s_prime.api_server == s.api_server);
            assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::ControllerStep(input) => {
            let (cid, recv, cr_key) = input;
            if cid == controller_id {
                // The vrs controller step
                lemma_main_inv_controller_step(cluster, controller_id, s, s_prime, recv, cr_key);
            } else {
                // Different controller, ongoing_reconciles(controller_id) unchanged
                assert(s.controller_and_externals.contains_key(controller_id));
                assert(s_prime.controller_and_externals.contains_key(controller_id));
                assert(s_prime.controller_and_externals[controller_id] == s.controller_and_externals[controller_id]);
                assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));
                assert(s_prime.api_server == s.api_server);
                lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
            }
        },
        Step::ScheduleControllerReconcileStep(input) => {
            let (cid, obj_key) = input;
            if cid == controller_id {
                // This step adds to scheduled_reconciles, not ongoing_reconciles
                assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));
            };
            assert(s_prime.api_server == s.api_server);
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::RestartControllerStep(cid) => {
            if cid == controller_id {
                // Restart clears ongoing_reconciles
                assert(s_prime.ongoing_reconciles(controller_id) == Map::<ObjectRef, OngoingReconcile>::empty());
                // Invariant trivially holds for empty map
                assert forall |key: ObjectRef|
                    #[trigger] s_prime.ongoing_reconciles(controller_id).contains_key(key)
                    implies false
                by {
                    assert(!Map::<ObjectRef, OngoingReconcile>::empty().contains_key(key));
                };
            } else {
                assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));
                assert(s_prime.api_server == s.api_server);
                lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
            }
        },
        Step::DisableCrashStep(cid) => {
            if cid == controller_id {
                assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));
            };
            assert(s_prime.api_server == s.api_server);
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::DropReqStep(_) => {
            // Network step, doesn't change resources or ongoing_reconciles
            assert(s_prime.api_server == s.api_server);
            assert(s_prime.controller_and_externals == s.controller_and_externals);
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::DisableReqDropStep => {
            assert(s_prime.api_server == s.api_server);
            assert(s_prime.controller_and_externals == s.controller_and_externals);
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::PodMonkeyStep(_) => {
            // Pod monkey sends messages, doesn't change resources directly
            assert(s_prime.api_server == s.api_server);
            assert(s_prime.controller_and_externals == s.controller_and_externals);
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::DisablePodMonkeyStep => {
            assert(s_prime.api_server == s.api_server);
            assert(s_prime.controller_and_externals == s.controller_and_externals);
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::ExternalStep(input) => {
            let (cid, _) = input;
            assert(s_prime.api_server == s.api_server);
            if cid == controller_id {
                assert(s_prime.ongoing_reconciles(controller_id) == s.ongoing_reconciles(controller_id));
            };
            lemma_main_inv_inductive_no_controller_change(cluster, controller_id, s, s_prime);
        },
        Step::StutterStep => {
            // No change at all
            assert(s_prime == s);
        },
    }
}

