                &&& resp_objs.filter(|o: DynamicObjectView| PodView::unmarshal(o).is_err()).len() == 0
                &&& forall |i| #![trigger resp_objs[i]] 0 <= i < resp_objs.len() ==>
                (
                    resp_objs[i].metadata.namespace.is_some()
