        assert(s_prime.ongoing_reconciles(controller_id)[key] == s.ongoing_reconciles(controller_id)[key]);
        let or = s.ongoing_reconciles(controller_id)[key];
        let state = VReplicaSetReconcileState::unmarshal(or.local_state).unwrap();
