// Prove invariant preserved by controller step
#[verifier(rlimit(200))]
proof fn lemma_main_inv_controller_step(
    cluster: Cluster, controller_id: int,
    s: ClusterState, s_prime: ClusterState,
    recv: Option<Message>,
    cr_key: Option<ObjectRef>,
)
    requires
        cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
        cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
        cluster.next_step(s, s_prime, Step::ControllerStep((controller_id, recv, cr_key))),
        each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)(s),
    ensures each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)(s_prime),
{
    // The controller step handles run_scheduled_reconcile, continue_reconcile, end_reconcile
    // ongoing_reconciles may change

    // The API server state is unchanged (controller doesn't modify etcd directly)
    assert(s_prime.api_server == s.api_server);

    // For keys in s_prime.ongoing_reconciles that were already in s.ongoing_reconciles
    // (with the same state), the invariant holds from s
    // For new keys (run_scheduled_reconcile), the initial state has filtered_pods: None, step: Init
    // For removed keys (end_reconcile), they're gone
    // For changed keys (continue_reconcile), need to trace the state change

    // Let's identify which action was taken
    let chosen_action = cluster.chosen_controller_next(controller_id);
    let input = (recv, cr_key);
    assert((chosen_action.precondition)(input, s));
    let (s_prime_ctrl, _) = (chosen_action.transition)(input, s);

    assert forall |key: ObjectRef|
